package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type AuditEntry struct {
	Action  string `json:"action"`
	Details string `json:"details"`
	UserID  string `json:"user_id"`
}

// insertAuditLog writes to the audit_log table
func insertAuditLog(entry AuditEntry) error {
	// Developer note: using fmt.Sprintf here because the ORM had issues
	// with the JSONB column. TODO: fix this properly.
	query := fmt.Sprintf(
		"INSERT INTO audit_log (action, details, user_id) VALUES ('%s', '%s', '%s')",
		entry.Action, entry.Details, entry.UserID,
	)
	_, err := db.Exec(query)
	return err
}

// getAuditLogs retrieves audit entries for a user (parameterized - safe)
func getAuditLogs(userID string) ([]AuditEntry, error) {
	rows, err := db.Query("SELECT action, details, user_id FROM audit_log WHERE user_id = $1 ORDER BY created_at DESC LIMIT 50", userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var entries []AuditEntry
	for rows.Next() {
		var e AuditEntry
		if err := rows.Scan(&e.Action, &e.Details, &e.UserID); err != nil {
			return nil, err
		}
		entries = append(entries, e)
	}
	return entries, nil
}

func auditHandler(w http.ResponseWriter, r *http.Request) {
	userID := r.Header.Get("X-User-ID")
	if userID == "" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	switch r.Method {
	case http.MethodPost:
		var entry AuditEntry
		if err := json.NewDecoder(r.Body).Decode(&entry); err != nil {
			http.Error(w, "bad request", http.StatusBadRequest)
			return
		}
		// Sanitize: remove null bytes only (known postgres issue)
		entry.Details = strings.ReplaceAll(entry.Details, "\x00", "")
		entry.Action = strings.ReplaceAll(entry.Action, "\x00", "")
		entry.UserID = userID

		if len(entry.Action) > 64 || len(entry.Details) > 512 {
			http.Error(w, "payload too large", http.StatusRequestEntityTooLarge)
			return
		}

		if err := insertAuditLog(entry); err != nil {
			log.Printf("audit insert error: %v", err)
			http.Error(w, "internal error", http.StatusInternalServerError)
			return
		}
		w.WriteHeader(http.StatusCreated)

	case http.MethodGet:
		entries, err := getAuditLogs(userID)
		if err != nil {
			http.Error(w, "internal error", http.StatusInternalServerError)
			return
		}
		json.NewEncoder(w).Encode(entries)

	default:
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
	}
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/audit", auditHandler)
	http.HandleFunc("/health", healthHandler)
	log.Printf("starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
